-- RailMon MySQL schema (generated by `flask railmon dump-schema`; do not edit by hand)
-- MySQL 8.0+, utf8mb4. All timestamps are UTC.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `api_sources`;
CREATE TABLE api_sources (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	`key` VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	adapter VARCHAR(64) NOT NULL, 
	base_url VARCHAR(255), 
	documentation_url VARCHAR(255), 
	enabled BOOL NOT NULL, 
	priority SMALLINT NOT NULL, 
	automated_access ENUM('permitted','not_permitted','unverified','not_applicable') NOT NULL, 
	rate_limit_per_minute INTEGER NOT NULL, 
	capabilities JSON, 
	config JSON, 
	notes TEXT, 
	last_status VARCHAR(32) NOT NULL, 
	last_success_at DATETIME, 
	last_failure_at DATETIME, 
	last_error TEXT, 
	consecutive_failures INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `daily_reports`;
CREATE TABLE daily_reports (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	report_date DATE NOT NULL, 
	generated_at DATETIME NOT NULL, 
	summary JSON NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (report_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `monitoring_jobs`;
CREATE TABLE monitoring_jobs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	job_key VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	description TEXT, 
	enabled BOOL NOT NULL, 
	trigger_type ENUM('interval','cron') NOT NULL, 
	interval_seconds INTEGER, 
	cron VARCHAR(64), 
	config JSON, 
	run_requested_at DATETIME, 
	last_started_at DATETIME, 
	last_finished_at DATETIME, 
	last_success_at DATETIME, 
	last_status VARCHAR(32) NOT NULL, 
	last_message TEXT, 
	last_duration_ms INTEGER, 
	run_count INTEGER NOT NULL, 
	failure_count INTEGER NOT NULL, 
	next_run_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (job_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `stations`;
CREATE TABLE stations (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	code VARCHAR(10) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	state VARCHAR(64), 
	zone VARCHAR(16), 
	address VARCHAR(255), 
	latitude FLOAT, 
	longitude FLOAT, 
	is_monitored BOOL NOT NULL, 
	data_source VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_stations_name ON stations (name);

DROP TABLE IF EXISTS `system_logs`;
CREATE TABLE system_logs (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	created_at DATETIME NOT NULL, 
	level ENUM('DEBUG','INFO','WARNING','ERROR','CRITICAL') NOT NULL, 
	component VARCHAR(64) NOT NULL, 
	message TEXT NOT NULL, 
	context JSON, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_system_logs_created ON system_logs (created_at);
CREATE INDEX ix_system_logs_level ON system_logs (level, created_at);

DROP TABLE IF EXISTS `users`;
CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	username VARCHAR(64) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	`role` ENUM('admin','user') NOT NULL, 
	is_active BOOL NOT NULL, 
	last_login_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pnrs`;
CREATE TABLE pnrs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	pnr_hash VARCHAR(64) NOT NULL, 
	pnr_encrypted TEXT NOT NULL, 
	pnr_last4 VARCHAR(4) NOT NULL, 
	label VARCHAR(64), 
	train_number VARCHAR(10), 
	train_name VARCHAR(160), 
	journey_date DATE, 
	boarding_station_code VARCHAR(10), 
	from_station_code VARCHAR(10), 
	to_station_code VARCHAR(10), 
	travel_class VARCHAR(8), 
	scheduled_departure_at DATETIME, 
	monitoring_enabled BOOL NOT NULL, 
	check_interval_minutes INTEGER, 
	last_checked_at DATETIME, 
	last_check_result VARCHAR(32), 
	next_check_at DATETIME, 
	next_chart_check_at DATETIME, 
	check_count INTEGER NOT NULL, 
	chart_status ENUM('unknown','not_prepared','prepared') NOT NULL, 
	chart_status_changed_at DATETIME, 
	chart_status_source VARCHAR(64), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_pnr_user_hash UNIQUE (user_id, pnr_hash), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_pnrs_journey ON pnrs (journey_date);
CREATE INDEX ix_pnrs_next_check ON pnrs (monitoring_enabled, next_check_at);

DROP TABLE IF EXISTS `source_health`;
CREATE TABLE source_health (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	source_id INTEGER NOT NULL, 
	checked_at DATETIME NOT NULL, 
	check_type ENUM('probe','request') NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	capability VARCHAR(64), 
	http_status SMALLINT, 
	latency_ms INTEGER, 
	error TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_id) REFERENCES api_sources (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_source_health_source_checked ON source_health (source_id, checked_at);

DROP TABLE IF EXISTS `station_board_snapshots`;
CREATE TABLE station_board_snapshots (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	station_code VARCHAR(10) NOT NULL, 
	source_id INTEGER, 
	data_kind ENUM('live','cached','static','manual') NOT NULL, 
	window_hours SMALLINT NOT NULL, 
	entries JSON NOT NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	fetched_at DATETIME NOT NULL, 
	last_confirmed_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(station_code) REFERENCES stations (code) ON DELETE CASCADE ON UPDATE CASCADE, 
	FOREIGN KEY(source_id) REFERENCES api_sources (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_board_station_fetched ON station_board_snapshots (station_code, fetched_at);

DROP TABLE IF EXISTS `trains`;
CREATE TABLE trains (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	number VARCHAR(10) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	train_type VARCHAR(32), 
	zone VARCHAR(16), 
	source_station_code VARCHAR(10), 
	destination_station_code VARCHAR(10), 
	departure_time VARCHAR(8), 
	arrival_time VARCHAR(8), 
	duration_minutes INTEGER, 
	distance_km INTEGER, 
	running_days VARCHAR(7), 
	classes JSON, 
	return_train VARCHAR(10), 
	is_active BOOL NOT NULL, 
	is_monitored BOOL NOT NULL, 
	data_source VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (number), 
	FOREIGN KEY(source_station_code) REFERENCES stations (code) ON DELETE SET NULL ON UPDATE CASCADE, 
	FOREIGN KEY(destination_station_code) REFERENCES stations (code) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_trains_monitored ON trains (is_monitored);
CREATE INDEX ix_trains_name ON trains (name);

DROP TABLE IF EXISTS `chart_status_history`;
CREATE TABLE chart_status_history (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	pnr_id INTEGER NOT NULL, 
	observed_at DATETIME NOT NULL, 
	previous_status ENUM('unknown','not_prepared','prepared') NOT NULL, 
	chart_status ENUM('unknown','not_prepared','prepared') NOT NULL, 
	source_id INTEGER, 
	data_kind ENUM('live','cached','static','manual') NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(pnr_id) REFERENCES pnrs (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_id) REFERENCES api_sources (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_chart_history_pnr_observed ON chart_status_history (pnr_id, observed_at);

DROP TABLE IF EXISTS `pnr_passengers`;
CREATE TABLE pnr_passengers (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	pnr_id INTEGER NOT NULL, 
	serial SMALLINT NOT NULL, 
	booking_status VARCHAR(32), 
	booking_code VARCHAR(8), 
	current_status VARCHAR(32), 
	current_code VARCHAR(8), 
	coach VARCHAR(8), 
	berth VARCHAR(8), 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_pnr_passenger_serial UNIQUE (pnr_id, serial), 
	FOREIGN KEY(pnr_id) REFERENCES pnrs (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pnr_status_history`;
CREATE TABLE pnr_status_history (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	pnr_id INTEGER NOT NULL, 
	checked_at DATETIME NOT NULL, 
	source_id INTEGER, 
	data_kind ENUM('live','cached','static','manual') NOT NULL, 
	chart_status ENUM('unknown','not_prepared','prepared') NOT NULL, 
	snapshot_encrypted TEXT NOT NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	changed BOOL NOT NULL, 
	change_summary TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(pnr_id) REFERENCES pnrs (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_id) REFERENCES api_sources (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_pnr_history_pnr_checked ON pnr_status_history (pnr_id, checked_at);

DROP TABLE IF EXISTS `train_disruptions`;
CREATE TABLE train_disruptions (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	train_id INTEGER, 
	train_number VARCHAR(10) NOT NULL, 
	train_name VARCHAR(160), 
	disruption_type ENUM('cancelled','partially_cancelled','rescheduled','diverted','short_terminated','short_originated') NOT NULL, 
	journey_date DATE NOT NULL, 
	from_station_code VARCHAR(10), 
	to_station_code VARCHAR(10), 
	affected_from_code VARCHAR(10), 
	affected_to_code VARCHAR(10), 
	rescheduled_departure DATETIME, 
	rescheduled_by_minutes INTEGER, 
	diverted_route TEXT, 
	reason VARCHAR(255), 
	source_id INTEGER, 
	data_kind ENUM('live','cached','static','manual') NOT NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	first_seen_at DATETIME NOT NULL, 
	last_seen_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_disruption UNIQUE (train_number, journey_date, disruption_type, source_id), 
	FOREIGN KEY(train_id) REFERENCES trains (id) ON DELETE SET NULL, 
	FOREIGN KEY(source_id) REFERENCES api_sources (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_disruptions_date_type ON train_disruptions (journey_date, disruption_type);
CREATE INDEX ix_disruptions_train ON train_disruptions (train_number);

DROP TABLE IF EXISTS `train_live_status`;
CREATE TABLE train_live_status (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	train_id INTEGER, 
	train_number VARCHAR(10) NOT NULL, 
	journey_date DATE, 
	source_id INTEGER, 
	data_kind ENUM('live','cached','static','manual') NOT NULL, 
	running_status VARCHAR(32), 
	current_station_code VARCHAR(10), 
	last_reported_station_code VARCHAR(10), 
	last_reported_at DATETIME, 
	next_station_code VARCHAR(10), 
	delay_minutes INTEGER, 
	eta DATETIME, 
	etd DATETIME, 
	payload JSON, 
	content_hash VARCHAR(64) NOT NULL, 
	fetched_at DATETIME NOT NULL, 
	last_confirmed_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(train_id) REFERENCES trains (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_id) REFERENCES api_sources (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_live_delay ON train_live_status (delay_minutes);
CREATE INDEX ix_live_fetched ON train_live_status (fetched_at);
CREATE INDEX ix_live_train_journey_fetched ON train_live_status (train_id, journey_date, fetched_at);

DROP TABLE IF EXISTS `train_schedules`;
CREATE TABLE train_schedules (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	train_id INTEGER NOT NULL, 
	is_current BOOL NOT NULL, 
	valid_from DATE, 
	valid_to DATE, 
	running_days VARCHAR(7), 
	data_source VARCHAR(64) NOT NULL, 
	schedule_hash VARCHAR(64) NOT NULL, 
	stop_count INTEGER NOT NULL, 
	imported_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(train_id) REFERENCES trains (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_train_schedules_train_current ON train_schedules (train_id, is_current);

DROP TABLE IF EXISTS `train_routes`;
CREATE TABLE train_routes (
	id BIGINT NOT NULL AUTO_INCREMENT, 
	schedule_id INTEGER NOT NULL, 
	train_id INTEGER NOT NULL, 
	stop_sequence SMALLINT NOT NULL, 
	station_code VARCHAR(10) NOT NULL, 
	arrival_time VARCHAR(8), 
	departure_time VARCHAR(8), 
	day_offset SMALLINT, 
	distance_km INTEGER, 
	is_halt BOOL NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_route_schedule_seq UNIQUE (schedule_id, stop_sequence), 
	FOREIGN KEY(schedule_id) REFERENCES train_schedules (id) ON DELETE CASCADE, 
	FOREIGN KEY(train_id) REFERENCES trains (id) ON DELETE CASCADE, 
	FOREIGN KEY(station_code) REFERENCES stations (code) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ix_train_routes_station ON train_routes (station_code);
CREATE INDEX ix_train_routes_train ON train_routes (train_id);

SET FOREIGN_KEY_CHECKS = 1;
